import json
n=0;msgs=[]
for l in open('session.jsonl',encoding='utf-8'):
    try:d=json.loads(l)
    except: continue
    if d.get('type')=='user' and isinstance(d.get('message',{}).get('content'),str) and not d.get('isMeta'):
        c=d['message']['content']
        if not c.startswith('<'): n+=1; msgs.append(c[:110].replace('\n',' '))
print(n)
for m in msgs[:40]: print('-',m)
EOF

